// Home.jsx
import React from "react";
import VideoCarousel from "./VideoCarousel";
import ActivityCarousel from "./ActivityCarousel";
import TestimonialGrid from "./TestimonialGrid";

/*
Update these asset paths or replace with remote URLs.
Place files in public/assets as listed below.
*/
const bannerVideos = [
  "https://cdn.pixabay.com/video/2019/07/03/25264-348298872_tiny.mp4",
  "https://cdn.pixabay.com/video/2020/04/29/36931-414316865_tiny.mp4",
  "https://cdn.pixabay.com/video/2021/02/25/65037-518467511_tiny.mp4",
  "https://cdn.pixabay.com/video/2019/11/04/28615-372986690_tiny.mp4"
];

const activityImages = [
  "/assets/activity1.jpg",
  "/assets/activity2.jpg",
  "/assets/activity3.jpg"
];

const testimonialVideos = [
  "https://cdn.pixabay.com/video/2021/08/17/87047-588888541_tiny.mp4",
  "https://cdn.pixabay.com/video/2022/10/24/136287-767869805_tiny.mp4",
  "https://cdn.pixabay.com/video/2021/10/25/92773-630387851_tiny.mp4",
  "https://cdn.pixabay.com/video/2021/07/28/84364-573927130_tiny.mp4"
];

export default function Home() {
  return (
    <main className="container home-page">
      {/* Banner video carousel */}
      <VideoCarousel videoList={bannerVideos} />

      {/* Welcome / Activities */}
      <section className="two-col card">
        <div className="left-col">
          <h2 style={{ color: "#0b3a73" }}>Welcome to Gandhi International Public School</h2>
          <p>
            Gandhi International Public School (GIPS) is dedicated to providing a high quality
            education that nurtures academic excellence, moral values and global citizenship.
          </p>
          <p>
            Our curriculum blends strong fundamentals, digital learning and extracurricular
            activities to create confident, creative and compassionate learners.
          </p>
          <p>
            Modern classrooms, experienced faculty and a caring environment make GIPS a place for
            students to grow.
          </p>
          <p>
            Admission open for session 2025-2026 — contact the school for details.
          </p>
        </div>

        <div className="right-col activities">
          <h3>Activities</h3>
          <ActivityCarousel images={activityImages} />
        </div>
      </section>

      {/* Three-column area */}
      <section className="three-col">
        <div className="col card">
          <h3>Latest News</h3>
          <div className="news-card">
            <h4>Admissions Open 2025-2026</h4>
            <p>
              Admissions are open for session 2025-2026. Apply online or contact the school office.
            </p>
            <p><strong>Admission Helpline:</strong> 123456789, 123456789</p>
          </div>
        </div>

        <div className="col card">
          <h3>Activity Calendar</h3>
          <div className="calendar-card">
            <div className="cal-top">
              <button title="Download" onClick={() => window.open("/assets/calendar.jpg", "_blank")}>⬇</button>
              <button title="Print" onClick={() => window.print()}>🖨</button>
              <button title="More">⋮</button>
            </div>
            <img src="/assets/calendar.jpg" alt="calendar" style={{ width: "100%", marginTop: 8 }} />
            <div style={{ marginTop: 8 }}>
              <a className="btn-small" href="/assets/calendar.jpg" target="_blank" rel="noreferrer">View</a>
            </div>
          </div>
        </div>

        <div className="col card">
          <h3>GIPS Video</h3>
          <div className="video-card">
            <iframe
              title="school-video"
              width="100%"
              height="200"
              src="https://www.youtube.com/embed/dQw4w9WgXcQ"
              frameBorder="0"
              allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
            <a className="btn-small" style={{ display: "inline-block", marginTop: 10 }} href="#">Five plants for good health</a>
          </div>
        </div>
      </section>

      {/* Testimonials */}
      <TestimonialGrid videos={testimonialVideos} />
    </main>
  );
}
